struct Order {
    let id: OrderID, customer: CustomerID
}
extension Order {
    init(fromCart cart: Cart) throws {
        guard !cart.items.isEmpty else { throw OrderError.emptyCart }
        id = OrderID(); customer = cart.customerID
    }
    static func rehydrate(id: OrderID, customer: CustomerID) -> Order {
        Order(id: id, customer: customer)      // memberwise init survives in an extension
    }
}

