struct Order: Decodable {
    let id: OrderID
    let customer: CustomerID
    init(from decoder: Decoder) throws {
        let raw = try RawOrder(from: decoder)          // wire shape stays separate
        guard !raw.customer.isEmpty else {
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "order: customer required"))
        }
        self.id = OrderID(raw.id)
        self.customer = CustomerID(raw.customer)
    }
}
